/** By ChatGPT */
var minimumChanges = function(s, k) {
    const n = s.length;

    // Valid proper divisors for every length
    const divisors = Array.from(
        { length: n + 1 }, () => []
    );

    for (let d = 1; d <= n / 2; d++) {
        for (let len = d * 2; len <= n; len += d) {
            divisors[len].push(d);
        }
    }

    // cost[i][j] = minimum changes to make
    // s[i...j] a semi-palindrome
    const cost = Array.from(
        { length: n }, () => Array(n).fill(Infinity)
    );

    for (let start = 0; start < n; start++) {
        for (let end = start + 1; end < n; end++) {
            const len = end - start + 1;

            for (const d of divisors[len]) {
                let changes = 0;

                for (let offset = 0; offset < d; offset++) {
                    let l = start + offset;
                    let r = end - d + 1 + offset;

                    while (l < r) {
                        if (s[l] !== s[r]) changes++;

                        l += d;
                        r -= d;
                    }
                }

                cost[start][end] = Math.min(
                    cost[start][end],
                    changes
                );
            }
        }
    }

    // Memoized partition DP
    const memo = Array.from(
        { length: n }, () => Array(k + 1)
    );

    const dfs = (start, remaining) => {
        if (remaining === 0) {
            return start === n ? 0 : Infinity;
        }

        // Need at least 2 characters per remaining part
        if (n - start < remaining * 2) {
            return Infinity;
        }

        if (memo[start][remaining] !== undefined) {
            return memo[start][remaining];
        }

        let best = Infinity;

        // Current part must have >= 2 characters.
        // Leave >= 2 for each remaining part.
        const maxEnd = n - 2 * (remaining - 1) - 1;

        for (let end = start + 1; end <= maxEnd; end++) {
            const total =
                cost[start][end] +
                dfs(end + 1, remaining - 1);

            best = Math.min(best, total);
        }

        return memo[start][remaining] = best;
    };

    return dfs(0, k);
};
